package authority

const dashboardHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jesuit Authority — Off-Air Lab</title><style>
:root{font-family:system-ui,Arial,sans-serif;color-scheme:dark}body{background:#07101c;color:#eaf3fb;margin:0;padding:20px}main{max-width:800px;margin:0 auto}h1{font-size:25px}h2{font-size:17px}section{padding:18px;margin-top:16px;border:1px solid #34445d;background:#101d30;border-radius:13px}button,select,input{font:inherit;border:1px solid #60718a;border-radius:8px;padding:10px;background:#233750;color:white}button{cursor:pointer;margin:4px}button:disabled{opacity:.45;cursor:not-allowed}.clock{font-size:66px;font-variant-numeric:tabular-nums;font-weight:900;text-align:center;letter-spacing:2px}.row{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.muted{color:#9cafc5}.badge{padding:6px 9px;border-radius:8px;background:#3b2720;color:#ffe3cb;font-size:12px}.warn{background:#392321;border-left:4px solid #f99b81;padding:12px;border-radius:7px}.scores{display:grid;grid-template-columns:1fr 1fr;gap:12px;text-align:center}.score{font-size:46px;font-weight:900}#status{min-height:50px;white-space:pre-line}small{color:#aac0d6}
</style></head><body><main><div class="row"><h1>Jesuit Clock & Command Authority</h1><span class="badge">OFF-AIR PROTOTYPE</span></div><div class="warn"><strong>NOT connected to the live Mac scoreboard, Firebase, Netlify, or OBS.</strong> This lab verifies the native clock and duplicate-command engine before integration. It does not change on-air scores.</div>
<section><div class="row"><div>Active sport: <strong id="sport">—</strong></div><div>Revision: <strong id="revision">—</strong></div></div><div class="clock" id="clock">--:--</div><div style="text-align:center"><button id="start">Start clock</button><button id="stop">Stop clock</button><button id="reset">Reset 1:00</button></div><p style="text-align:center"><small>Clock continues in the Mac-side process, even if this browser tab closes.</small></p></section>
<section><h2>Scores</h2><div class="scores"><div><b>HOME</b><div class="score" id="home">—</div><button id="homeplus">+1</button><button id="homeminus">−1</button></div><div><b>AWAY</b><div class="score" id="away">—</div><button id="awayplus">+1</button><button id="awayminus">−1</button></div></div><div class="row"><span>Period: <b id="period">—</b></span><div><button id="periodminus">− period</button><button id="periodplus">+ period</button></div></div></section>
<section><h2>Safe game setup</h2><label>Sport <select id="newSport"><option>football</option><option>basketball</option><option>lacrosse</option><option>soccer</option><option>baseball</option></select></label><button id="newGame">Start new off-air game</button><p class="muted">Starting a new game clears the current scores and accepted command IDs. It requires confirmation.</p></section>
<section><h2>Lab controls</h2><button id="quit">Save &amp; close Authority Lab</button><p class="muted">This shuts down the off-air Mac authority and pauses its clock. Reopen the app later to resume testing.</p></section><section><h2>Command receipts</h2><div id="status" class="muted">Connecting to local authority…</div><p class="muted"><small>Each action has a unique command ID and expected revision. Conflicts require state refresh and deliberate retry; uncertain requests are never blindly replayed.</small></p></section>
</main><script>
(()=>{'use strict';const TOKEN='__OPERATOR_TOKEN__',Q=id=>document.getElementById(id);let state=null,busy=false;
const id=()=>{let a=new Uint8Array(18);crypto.getRandomValues(a);return [...a].map(x=>x.toString(16).padStart(2,'0')).join('')};
const status=t=>{Q('status').textContent=t};
const fmt=ms=>{const sec=Math.ceil(Math.max(0,ms)/1000);return String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')};
const draw=s=>{state=s;Q('sport').textContent=s.sport.toUpperCase();Q('revision').textContent=s.revision;Q('clock').textContent=fmt(s.clock.remainingMs);Q('home').textContent=s.homeScore;Q('away').textContent=s.awayScore;Q('period').textContent=s.period;};
async function refresh(){try{const r=await fetch('/api/v2/state',{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);if(!busy)draw(await r.json());}catch(e){status('Local authority unavailable: '+e.message)}}
async function send(type,payload={}){if(busy||!state)return;busy=true;const cmd={protocol:2,gameId:state.gameId,sport:state.sport,id:id(),expectedRevision:state.revision,type,payload};status('Sending '+type+' …');try{const r=await fetch('/api/v2/commands',{method:'POST',headers:{'Content-Type':'application/json','X-Jesuit-Operator-Token':TOKEN},body:JSON.stringify(cmd)});const a=await r.json();if(!r.ok){status(type+' '+a.status+': '+(a.reason||r.status)+'\nState refreshed. Review before trying again.');}else{status(type+' '+a.status+' · revision '+a.revision+' · ID '+cmd.id+'\nThis is a local engine receipt, NOT OBS confirmation.');}}catch(e){status('UNCERTAIN: '+type+' may have been applied. Do not click again until reviewing state. '+e.message);}finally{busy=false;await refresh()}}
Q('start').onclick=()=>send('clock.start');Q('stop').onclick=()=>send('clock.stop');Q('reset').onclick=()=>send('clock.reset',{remainingMs:60000});Q('homeplus').onclick=()=>send('score.add',{team:'home',points:1});Q('homeminus').onclick=()=>send('score.add',{team:'home',points:-1});Q('awayplus').onclick=()=>send('score.add',{team:'away',points:1});Q('awayminus').onclick=()=>send('score.add',{team:'away',points:-1});Q('periodplus').onclick=()=>state&&send('period.set',{period:Math.min(20,state.period+1)});Q('periodminus').onclick=()=>state&&send('period.set',{period:Math.max(1,state.period-1)});
Q('newGame').onclick=async()=>{if(busy||!state)return;if(!confirm('START A NEW OFF-AIR GAME? Scores reset to zero. This does not touch OBS.'))return;busy=true;try{const r=await fetch('/api/v2/games',{method:'POST',headers:{'Content-Type':'application/json','X-Jesuit-Operator-Token':TOKEN},body:JSON.stringify({sport:Q('newSport').value,expectedGameId:state.gameId,confirm:'START NEW OFF-AIR GAME'})});if(!r.ok)throw Error('HTTP '+r.status);status('New off-air game created.');}catch(e){status('New game failed: '+e.message)}finally{busy=false;await refresh()}};
Q('quit').onclick=async()=>{if(!confirm('PAUSE and close this OFF-AIR Authority Lab?'))return;busy=true;try{const r=await fetch('/api/v2/shutdown',{method:'POST',headers:{'Content-Type':'application/json','X-Jesuit-Operator-Token':TOKEN},body:'{}'});if(!r.ok)throw Error('HTTP '+r.status);status('Authority closed safely; you may close this tab.');}catch(e){status('Shutdown failed: '+e.message)} };refresh();setInterval(refresh,700);
})();
</script></body></html>`
